<script setup>
import { computed, reactive, ref } from 'vue';
import Icon from '../components/Icon.vue'; import Modal from '../components/Modal.vue';
import { data, saveRecord, notify } from '../store.js'; import { idEqual } from '../domain.js';
const kind = ref('departments'), editing = ref(false), form = reactive({}), error = ref(''), saving = ref(false);
const titles = { departments: 'Подразделения', positions: 'Должности', access_levels: 'Уровни доступа' };
const rows = computed(() => data[kind.value]);
const count = id => data.employees.filter(e => idEqual(e[kind.value === 'departments' ? 'departmentId' : kind.value === 'positions' ? 'positionId' : 'accessLevelId'], id)).length;
function edit(item) { Object.keys(form).forEach(k => delete form[k]); Object.assign(form, item || { name: '', ...(kind.value === 'access_levels' ? { description: '' } : {}) }); error.value = ''; editing.value = true; }
async function submit() { saving.value = true; error.value = ''; try { if (!form.name.trim()) throw new Error('Укажите название.'); if (rows.value.some(x => !idEqual(x.id, form.id) && x.name.toLowerCase() === form.name.trim().toLowerCase())) throw new Error('Такое название уже существует.'); await saveRecord(kind.value, { ...form, name: form.name.trim() }); editing.value = false; notify('Запись сохранена.'); } catch (e) { error.value = e.message; } finally { saving.value = false; } }
</script>
<template><div class="page-header"><div><span class="eyebrow">СТРУКТУРА ОРГАНИЗАЦИИ</span><h1>Справочники<span class="heading-dot">.</span></h1><p>Подразделения, должности и уровни доступа сотрудников.</p></div><button class="button primary" @click="edit()"><Icon name="plus" :size="18" />Добавить запись</button></div><div class="page-tabs"><button v-for="(title, key) in titles" :key="key" :class="{ active: kind === key }" @click="kind = key">{{ title }}<span>{{ data[key].length }}</span></button></div><section class="panel"><div v-if="!rows.length" class="empty-state"><Icon name="folder" :size="36" /><h3>Справочник пока пуст</h3><p>Добавьте первую запись.</p></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Название</th><th v-if="kind === 'access_levels'">Описание</th><th>Сотрудников</th><th></th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><div class="person-cell"><span class="room-symbol"><Icon :name="kind === 'departments' ? 'building' : kind === 'positions' ? 'briefcase' : 'key'" :size="19" /></span><strong>{{ item.name }}</strong></div></td><td v-if="kind === 'access_levels'" class="muted">{{ item.description || '—' }}</td><td>{{ count(item.id) }}</td><td><button class="icon-button" :aria-label="`Изменить ${item.name}`" @click="edit(item)"><Icon name="edit" :size="17" /></button></td></tr></tbody></table></div></section><Modal v-if="editing" :title="form.id ? 'Редактировать запись' : 'Новая запись'" @close="!saving && (editing = false)"><form id="directory-form" @submit.prevent="submit"><label>Название<input v-model="form.name" required maxlength="100" /></label><label v-if="kind === 'access_levels'">Описание<textarea v-model="form.description" rows="3" maxlength="300"></textarea></label><div v-if="error" class="alert-box" role="alert">{{ error }}</div></form><template #footer><button class="button" :disabled="saving" @click="editing = false">Отмена</button><button class="button primary" form="directory-form" type="submit" :disabled="saving">Сохранить</button></template></Modal></template>
